+QString ImageBackend::keepUsersWallpaper(const QString &wallpaper)
+{
+    const QUrl url(wallpaper);
+    const QFileInfo info(url.toLocalFile());
+    if (!url.isLocalFile() || !info.isFile()) {
+        return wallpaper;
+    }
+
+    const QString path = info.absoluteFilePath();
+    const QStringList wallpaperDirs = QStandardPaths::locateAll(QStandardPaths::GenericDataLocation, u"wallpapers/"_s, QStandardPaths::LocateDirectory);
+    if (std::ranges::any_of(wallpaperDirs, [&path](const QString &dir) {
+            return path.startsWith(QDir(dir).absolutePath() + u'/');
+        })) {
+        return wallpaper;
+    }
+
+    const QString localDir = QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + u"/wallpapers/"_s;
+    QString target = localDir + info.fileName();
+    if (QFileInfo::exists(target)) {
+        QFile source(path);
+        QFile existing(target);
+        if (!source.open(QIODevice::ReadOnly) || !existing.open(QIODevice::ReadOnly) || source.size() != existing.size()
+            || source.readAll() != existing.readAll()) {
+            target = localDir + KFileUtils::suggestName(QUrl::fromLocalFile(localDir), info.fileName());
+        }
+    }
+
+    if (!QFileInfo::exists(target) && (!QDir().mkpath(localDir) || !QFile::copy(path, target))) {
+        qWarning() << "Failed to copy wallpaper" << path << "to" << target;
+        return wallpaper;
+    }
+
+    KConfigGroup cfg(KSharedConfig::openConfig(u"plasmarc"_s), u"Wallpapers"_s);
+    QStringList usersWallpapers = cfg.readEntry("usersWallpapers", QStringList{});
+    if (usersWallpapers.removeAll(path) + usersWallpapers.removeAll(QUrl::fromLocalFile(path).toString()) > 0) {
+        cfg.writeEntry("usersWallpapers", usersWallpapers);
+        cfg.sync();
+    }
+
+    if (m_model) {
+        m_model->removeBackground(QUrl::fromLocalFile(path));
+        m_model->addBackground(QUrl::fromLocalFile(target));
+    }
+
+    return QUrl::fromLocalFile(target).toString();
+}
